import{esc,safeUrl}from'../../ui/format.js';
export function specificationFields(el){if(!el.specs?.length)return '';return `<details class="property-section" open><summary>Specificații documentate</summary>${el.reference?`<p class="small">${esc(el.reference.name)}<br>${esc(el.reference.configuration)}<br><a href="${esc(safeUrl(el.reference.url))}" target="_blank" rel="noopener noreferrer">Sursa producătorului ↗</a> · verificat ${esc(el.reference.checked)}</p>`:''}${el.specs.map((s,i)=>`<label>${esc(s.name)} <small>${esc(s.unit)}</small><input name="spec-${i}" type="number" step="any" value="${s.value}" required><small>${s.value===s.referenceValue?'Valoare producător':'Modificat local'} · referință: ${s.referenceValue} ${esc(s.unit)}</small></label>`).join('')}<p class="small muted">Specificații descriptive. Nu se convertesc automat în timp de ciclu, consum mediu sau rată de producție.</p></details>`}
export function parameterProvenance(el,k){const v=el.calibration?.[k];return `<span class="param-provenance ${v?.status==='required'?'needs-data':''}">${v?.status==='measured'?'● Măsurat':v?.status==='manufacturer'?'● Producător':v?.status==='required'?'○ De calibrat':'○ Ipoteză'} <button type="button" data-calibrate="${esc(el.id)}" data-param="${k}">Proveniență</button></span>`}
